from google.cloud import monitoring_v3
import time
from typing import List, Dict, Any

def query_metric_by_resource_label(
    project_id: str,
    metric_type: str,
    resource_label_key: str,
    resource_label_value: str,
    minutes_ago: int = 20,
) -> List[Dict[str, Any]]:
    """
    Queries metric data from Google Cloud Monitoring, filtered by a resource label.

    Args:
        project_id: Your Google Cloud project ID.
        metric_type: The metric type to query (e.g., "compute.googleapis.com/instance/cpu/utilization").
        resource_label_key: The resource label to filter by (e.g., "zone").
        resource_label_value: The value of the resource label (e.g., "us-central1-a").
        minutes_ago: The duration in minutes to look back for metric data.

    Returns:
        A list of dictionaries, where each dictionary represents a time series.
    """
    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    now = time.time()
    seconds = int(now)
    nanos = int((now - seconds) * 10**9)
    interval = monitoring_v3.TimeInterval(
        {
            "end_time": {"seconds": seconds, "nanos": nanos},
            "start_time": {"seconds": (seconds - minutes_ago * 60), "nanos": nanos},
        }
    )

    filter_str = (
        f'metric.type = "{metric_type}" AND '
        f'resource.labels.{resource_label_key} = "{resource_label_value}"'
    )

    # Retrieve time series data
    results = client.list_time_series(
        request={
            "name": project_name,
            "filter": filter_str,
            "interval": interval,
            "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
        }
    )

    # Process and format the response
    time_series_data = []
    for result in results:
        series = {
            "metric": {
                "type": result.metric.type,
                "labels": dict(result.metric.labels),
            },
            "resource": {
                "type": result.resource.type,
                "labels": dict(result.resource.labels),
            },
            "points": [],
        }
        for point in result.points:
            # The value type can vary, handle a few common ones
            if result.value_type == monitoring_v3.MetricDescriptor.ValueType.DOUBLE:
                value = point.value.double_value
            elif result.value_type == monitoring_v3.MetricDescriptor.ValueType.INT64:
                value = point.value.int64_value
            elif result.value_type == monitoring_v3.MetricDescriptor.ValueType.BOOL:
                value = point.value.bool_value
            else:
                value = str(point.value)

            series["points"].append(
                {
                    "timestamp": point.interval.end_time.rfc3339(),
                    "value": value,
                }
            )
        time_series_data.append(series)

    return time_series_data
